# Reviewed: NEW-LOCATORs moved into InventoryPage (sort_by, item names and prices),
# skip markers removed, AC-1..3 now check the whole order, not only the first and last item.
import pytest
from playwright.sync_api import expect
from sites.saucedemo.pages.login_page import LoginPage
from sites.saucedemo.pages.inventory_page import InventoryPage
from sites.saucedemo.config import Config


class TestInventorySorting:

    @pytest.fixture(autouse=True)
    def login(self, page):
        login_page = LoginPage(page)
        login_page.navigate()
        login_page.login(Config.STANDARD_USER, Config.PASSWORD)

    def test_sort_price_low_to_high(self, page):
        """AC-1: Choosing "Price (low to high)" lists the products by price ascending:
        the first product is "Sauce Labs Onesie" ($7.99) and the last is
        "Sauce Labs Fleece Jacket" ($49.99)."""
        inventory_page = InventoryPage(page)
        inventory_page.sort_by("lohi")
        expect(inventory_page.item_names.first).to_have_text("Sauce Labs Onesie")  # waits for the re-sort

        names = inventory_page.get_item_names()
        prices = inventory_page.get_item_prices()
        assert prices == sorted(prices)
        assert (names[0], prices[0]) == ("Sauce Labs Onesie", 7.99)
        assert (names[-1], prices[-1]) == ("Sauce Labs Fleece Jacket", 49.99)

    def test_sort_price_high_to_low(self, page):
        """AC-2: Choosing "Price (high to low)" lists the products by price descending:
        the first product is "Sauce Labs Fleece Jacket" ($49.99) and the last is
        "Sauce Labs Onesie" ($7.99)."""
        inventory_page = InventoryPage(page)
        inventory_page.sort_by("hilo")
        expect(inventory_page.item_names.first).to_have_text("Sauce Labs Fleece Jacket")

        names = inventory_page.get_item_names()
        prices = inventory_page.get_item_prices()
        assert prices == sorted(prices, reverse=True)
        assert (names[0], prices[0]) == ("Sauce Labs Fleece Jacket", 49.99)
        assert (names[-1], prices[-1]) == ("Sauce Labs Onesie", 7.99)

    def test_sort_name_z_to_a(self, page):
        """AC-3: Choosing "Name (Z to A)" lists the products by name descending:
        the first product is "Test.allTheThings() T-Shirt (Red)" and the last is
        "Sauce Labs Backpack"."""
        inventory_page = InventoryPage(page)
        inventory_page.sort_by("za")
        expect(inventory_page.item_names.first).to_have_text("Test.allTheThings() T-Shirt (Red)")

        names = inventory_page.get_item_names()
        assert names == sorted(names, reverse=True)
        assert names[0] == "Test.allTheThings() T-Shirt (Red)"
        assert names[-1] == "Sauce Labs Backpack"
